  if (deployment4) {
    const recognized = (kind === "concentrated" ? deployment4.recognized.concentratedFactories : deployment4.recognized.compoundingFactories).find((entry) => addressEquals(entry.address, factory));
    if (!recognized) throw new RangeError(`factory ${factory} is not recognized by the selected deployment`);
    const pinnedHash = recognized.runtimeCodeHash ?? deployment4.runtimeCodeHashes?.[factory.toLowerCase()];
    if (pinnedHash && pinnedHash.toLowerCase() !== profile.factoryRuntimeCodeHash.toLowerCase()) {
      throw new RangeError(`factory ${factory} profile conflicts with the selected deployment runtime hash`);
    }
  }
  const activeFactory = deployment4 && profile.lifecycle === "current" ? kind === "concentrated" ? deployment4.active.launch.concentratedFactory : deployment4.active.launch.compoundingFactory : deployment4 ? void 0 : activeFactoryForProfile(profile);
  if (activeFactory && !addressEquals(activeFactory, profile.factory)) {
    throw new RangeError(
      `current ${kind} factory profile is out of sync with the active deployment catalog`
    );
  }
  const [factoryCode, poolCode, registered, reportedImplementation] = await Promise.all([
    codeAtBlock(client2, factory, blockNumber),
    codeAtBlock(client2, pool, blockNumber),
    readAtBlock(client2, factory, "isPool", [pool], blockNumber),
    readAtBlock(client2, factory, "poolImplementation", [], blockNumber)
  ]);
